'pay-settlement':id=>form('Registrar una transferencia.','pay-settlement',`<input type="hidden" name="id" value="${esc(id)}">`+input('Referencia de transferencia','reference','DEMO-TRANSFER-001')+`<label class="check-label"><input type="checkbox" required name="checked">Confirmo que el registro es una simulación.</label>`,'Marcar pagada en la muestra','Este prototipo registra una referencia; no ejecuta una transferencia.'),
 moderate:id=>{const r=reviews.find(r=>r.id===id);if(r)confirmAction(r.hidden?'Restaurar contenido.':'Ocultar contenido.','La acción de ejemplo cambia su visibilidad en la lámina.','confirm-moderate',id);},
