'ledger-group':id=>{const g=ledgerGroups.find(g=>g.id===id);if(g)modal(g.concept,table(['Cuenta','Debe','Haber'],g.lines.map(l=>[`${l[1]}<span class="secondary code">${l[0]}</span>`,clp(l[2]),clp(l[3])]))+`<div class="banner lime block"><strong>Debe = Haber · ${clp(g.lines.reduce((s,l)=>s+l[2],0))}</strong></div><p class="notice">Grupo ilustrativo, sin hash criptográfico calculado. El inventario se valora a costo; $30.000 de consumo facial implican $16.500 de costo en el ejemplo de VM-3816.</p>`,g.id+' · '+g.date);},
