window.vamoaDemo={transactions,merchants,history,getState:()=>({...state}),ledgerGroups};
let resizeTimer,portalViewportWidth=window.innerWidth;function refreshPortalWidth(){if(chartDrag){resizeTimer=setTimeout(refreshPortalWidth,100);return;}if(!document.getElementById('dialog').open)render();}window.addEventListener('resize',()=>{if(window.innerWidth===portalViewportWidth)return;portalViewportWidth=window.innerWidth;clearTimeout(resizeTimer);resizeTimer=setTimeout(refreshPortalWidth,180);});

